use vstd::prelude::*;

verus! {

    // A two‐case tagged type for 64‐bit date‐time values.
    #[derive(Copy, Clone, PartialEq, Eq)]
    datatype DateTime64 {
        Nat,
        Valid(v: i64),
    }

    // A pure specification of “is this the Nat case?”
    spec fn is_nat_spec(d: DateTime64) -> bool {
        match d {
            DateTime64::Nat => true,
            DateTime64::Valid(_) => false,
        }
    }

    // Given a vector of DateTime64, produce a vector of booleans
    // of the same length such that for each index i:
    //    result[i] == true  iff x[i] is Nat
    //    result[i] == false iff x[i] is Valid(_)
    fn isnat(x: Vec<DateTime64>) -> Vec<bool>
        ensures
            // preserves length
            result.len() == x.len(),
            // pointwise correctness
            forall |i: usize| i < x.len() ==> result[i] == is_nat_spec(x[i]),
    {
        let mut res: Vec<bool> = Vec::new();
        let mut i: usize = 0;
        // iterate over all positions
        while i < x.len()
            invariant
                // loop index never exceeds input length
                i <= x.len(),
                // the result vector length tracks i
                res.len() == i,
                // prefix correctness: for all j < i, res[j] matches x[j]
                forall |j: usize| j < i ==> res[j] == is_nat_spec(x[j]),
            decreases x.len() - i,
        {
            // inspect the i‐th element
            let b = match x[i] {
                DateTime64::Nat       => true,
                DateTime64::Valid(_)  => false,
            };
            // append the boolean to the result
            res.push(b);
            // advance
            i = i + 1;
        }
        res
    }

}

